"""
二分探索 (Binary Search) チートシート & めぐる式二分探索
Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)

【bisectの早見表】
ソート済みリスト A に対し:
- bisect_left(A, x) : x 以上の最小インデックス (挿入可能最左)
- bisect_right(A, x): x より大きい最小インデックス (挿入可能最右)
- x 以下の最大値の index : bisect_right(A, x) - 1
- x 未満の最大値の index : bisect_left(A, x) - 1
- x の出現個数          : bisect_right(A, x) - bisect_left(A, x)

【めぐる式二分探索 (bin_search)】
条件を満たす境界を探索。ok と ng の境界を log2(|ok - ng|) 回で特定。
- ok: 必ず条件を満たす初期値
- ng: 必ず条件を満たさない初期値
- fn: 条件判定関数 fn(mid) -> bool
"""

# https://github.com/ddfkit/acsampl/blob/main/bisect_.py
# Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)
def bin_search(ok,ng,fn):
    while abs(ok-ng)>1:
        m=(ok+ng)//2
        if fn(m):ok=m
        else:ng=m
    return ok

# https://github.com/ddfkit/acsampl/blob/main/bisect_.py
# Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)
def bin_search_float(ok,ng,fn,eps=1e-9,loop=100):
    for _ in range(loop):
        m=(ok+ng)/2
        if fn(m):ok=m
        else:ng=m
    return ok

if __name__ == "__main__":
    import bisect

    # Aはソートされていなければならない
    A = [1, 2, 3, 3, 3, 5, 6]
    #    0  1  2  3  4  5  6

    # 順序を保ったまま挿入できる一番左。
    # なので指定以上の最小インデクス
    assert bisect.bisect_left(A, 3) == 2
    assert bisect.bisect_left(A, 4) == 5

    # 順序を保ったまま挿入できる一番右。
    # なので指定を超える最小インデクス
    assert bisect.bisect_right(A, 3) == 5
    assert bisect.bisect_right(A, 4) == 5

    # 出現個数: bisect_right - bisect_left
    assert bisect.bisect_right(A, 3) - bisect.bisect_left(A, 3) == 3

    # x 以下の最大要素のインデックス
    assert bisect.bisect_right(A, 3) - 1 == 4

    # x 未満の最大要素のインデックス
    assert bisect.bisect_left(A, 3) - 1 == 1

    # --- めぐる式二分探索 ---
    # x**2 <= 50 を満たす最大の整数 x
    res = bin_search(0, 100, lambda x: x * x <= 50)
    assert res == 7

    # sqrt(2) の浮動小数点探索
    sq2 = bin_search_float(1.0, 2.0, lambda x: x * x <= 2.0)
    assert abs(sq2 - 1.41421356) < 1e-6
    print("bisect_.py: all tests passed!")
